@section('content')<div x-data="rambuShow({{ $id }})" x-init="init()" x-cloak><div class="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="text-sm text-slate-600">Informasi lengkap aset</p><h2 class="mt-1 text-2xl font-semibold text-navy-900">Detail <span x-text="item?code(item):'Rambu'">Rambu</span></h2></div><div class="flex gap-2"><a href="{{ route('assets.rambu.index') }}" class="action-button">Kembali</a><a href="{{ route('assets.rambu.edit',$id) }}" class="action-button-primary">Edit</a></div></div><div x-show="error" class="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700" x-text="error"></div><div x-show="loading" class="rounded-2xl border border-border bg-white p-8 text-sm text-slate-500">Memuat detail...</div><div x-show="item&&!loading" class="grid gap-5 lg:grid-cols-[minmax(0,1fr)_340px]"><section class="rounded-2xl border border-border bg-white p-6 shadow-sm"><div class="mb-5 rounded-xl border border-teal-100 bg-teal-50 p-4"><p class="detail-label">Kode aset</p><p class="mt-1 text-lg font-semibold text-navy-900" x-text="item?.qr_code || code(item)"></p><div class="mt-3 flex flex-wrap gap-2"><button type="button" @click="printQr()" class="action-button">Cetak QR</button><button type="button" @click="downloadQr()" class="action-button-primary">Unduh QR</button></div><div class="mt-3 flex justify-center"><img :src="qrUrl()" :alt="`QR ${item?.qr_code || code(item)}`" class="h-48 w-48" loading="lazy" x-on:error="qrError = 'QR gagal dimuat. Coba muat ulang halaman.'"><p x-show="qrError" class="mt-2 text-center text-xs text-red-600" x-text="qrError"></p></div></div><div class="grid gap-5 sm:grid-cols-2"><div><p class="detail-label">Jenis rambu</p><p class="detail-value" x-text="item?.jenis_rambu"></p></div><div><p class="detail-label">Status</p><span class="inline-flex rounded-full px-2.5 py-1 text-xs" :class="statusClass(item?.status)" x-text="item?.status"></span></div><div><p class="detail-label">Alamat</p><p class="detail-value" x-text="item?.alamat"></p></div><div><p class="detail-label">Desa / Kecamatan</p><p class="detail-value" x-text="`${item?.desa?.desa||'-'} / ${item?.desa?.kecamatan?.kecamatan||item?.desa?.kec_dtks||'-'}`"></p></div><div><p class="detail-label">Sumber dana</p><p class="detail-value" x-text="item?.sumber_dana?.nama_sumber||'-'"></p></div><div><p class="detail-label">Koordinat</p><p class="detail-value" x-text="`${item?.latitude||'-'}, ${item?.longitude||'-'}`"></p></div><div><p class="detail-label">Tahun anggaran</p><p class="detail-value" x-text="item?.tahun_anggaran||'-'"></p></div></div></section><aside class="rounded-2xl border border-border bg-white p-5 shadow-sm"><p class="detail-label">Foto aset</p><template x-if="item?.foto"><a :href="photo(item.foto)" target="_blank"><img :src="photo(item.foto)" alt="Foto Rambu" class="mt-3 aspect-[4/3] w-full rounded-xl object-cover"></a></template><p x-show="!item?.foto" class="mt-3 rounded-xl bg-slate-50 p-8 text-center text-sm text-slate-500">Belum ada foto.</p></aside></div></div><script>function rambuShow(id){return{item:null,qrError:'',loading:true,error:'',async init(){try{this.item=(await window.axios.get(`/api/rambu/${id}`)).data}catch(e){this.error=e.response?.data?.message||'Gagal memuat detail Rambu.'}finally{this.loading=false}},printQr(){const w=window.open(this.qrUrl(),'_blank');w?.addEventListener('load',()=>w.print())},downloadQr(){const a=document.createElement('a');a.href=this.qrUrl();a.download=`${this.item?.qr_code||this.code(this.item)}.svg`;a.click()},qrUrl(){return `/assets/rambu/${this.item?.id}/qr`},code(x){return`RAMBU-${String(x.id).padStart(4,'0')}`},statusClass(s){return s==='baik'?'bg-teal-100 text-teal-800':s==='rusak'?'bg-red-100 text-red-800':'bg-yellow-100 text-yellow-800'},photo(p){return p?.startsWith('http')?p:`/storage/${p}`}}}</script>@endsection
